from urllib.parse import urlsplit, urlunsplit, parse_qsl
import re


def _replace_hostname(parsed, new_host):
    """Replace only the hostname while preserving user info and port."""
    netloc = parsed.netloc

    # Preserve user information, if present.
    userinfo = ""
    hostport = netloc
    if "@" in netloc:
        userinfo, hostport = netloc.rsplit("@", 1)
        userinfo += "@"

    # Preserve the original port.
    port = ""
    if hostport.startswith("["):  # IPv6 address
        end = hostport.find("]")
        if end != -1:
            remainder = hostport[end + 1:]
            if remainder.startswith(":"):
                port = remainder
    else:
        match = re.search(r":\d+$", hostport)
        if match:
            port = match.group(0)

    # Bracket an IPv6 replacement host when necessary.
    if ":" in new_host and not new_host.startswith("["):
        new_host = f"[{new_host}]"

    new_netloc = f"{userinfo}{new_host}{port}"
    return parsed._replace(netloc=new_netloc)


def _host_matches(host, match_value):
    if host is None:
        return False

    host = host.lower()
    match_value = match_value.lower()

    if match_value.startswith("*."):
        suffix = match_value[2:]
        # The base domain itself does not match. At least one label is required.
        return host.endswith("." + suffix) and host != suffix

    return host == match_value


def apply_rewrite_rules(rules, urls):
    """
    Apply the first matching rewrite rule to each URL.

    Returns:
        A list containing rewritten URLs or None for blocked URLs.
    """
    results = []

    for url in urls:
        parsed = urlsplit(url)
        rewritten_url = url

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            matched = False

            if match_type == "path_prefix":
                matched = parsed.path.startswith(match_value)

            elif match_type == "host":
                matched = _host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                query_params = parse_qsl(
                    parsed.query,
                    keep_blank_values=True
                )
                matched = any(name == match_value for name, _ in query_params)

            else:
                raise ValueError(f"Unknown match_type: {match_type}")

            if not matched:
                continue

            if action == "block":
                rewritten_url = None

            elif action == "strip_prefix":
                prefix = rule["action_value"]
                path = parsed.path

                if path.startswith(prefix):
                    path = path[len(prefix):]

                if not path:
                    path = "/"

                rewritten_url = urlunsplit(parsed._replace(path=path))

            elif action == "redirect_host":
                rewritten_url = urlunsplit(
                    _replace_hostname(parsed, rule["action_value"])
                )

            elif action == "add_query_param":
                addition = rule["action_value"]
                query = parsed.query

                if query:
                    query = f"{query}&{addition}"
                else:
                    query = addition

                rewritten_url = urlunsplit(parsed._replace(query=query))

            else:
                raise ValueError(f"Unknown action: {action}")

            # Only the first matching rule is applied.
            break

        results.append(rewritten_url)

    return results
